function Assert-Checks([object]$r,[string]$label){$bad=@();foreach($p in $r.checks.PSObject.Properties){if([bool]$p.Value){Write-Output "PASS guard=$label.$($p.Name)"}else{$bad+=@($p.Name);[Console]::Error.WriteLine("FAIL guard=$label.$($p.Name)")}};if($bad.Count-ne0-or-not[bool]$r.all_checks_pass){throw "$label failed $($bad.Count) guard(s)."}}
function Read-Hidden([string]$label){$s=Read-Host $label -AsSecureString;try{if($s.Length-eq0){throw 'Empty value.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Login([string]$email,[string]$password){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/auth/v1/token?grant_type=password');try{$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{email=$email;password=$password}-Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{if(-not$x.IsSuccessStatusCode){throw "Login HTTP $([int]$x.StatusCode)"};$b=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()|ConvertFrom-Json;[pscustomobject]@{Id=[guid]$b.user.id;Token=[string]$b.access_token}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function SendAs([string]$token,[string]$action,[object]$request){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token);$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{action=$action;request=$request}-Depth 30 -Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function PsqlJson([string]$file,[hashtable]$extra){$op=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$oc=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$a=@('-X','-w','-qAt','-v','ON_ERROR_STOP=1','-d','host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full','-v',"repository_id=$($script:planDoc.repository_id)",'-v',"first_submission_id=$($script:planDoc.submission_id)",'-v',"second_submission_id=$($script:priorReceipt.submission_id)",'-v',"new_contract_id=$script:contractId",'-v',"new_submission_id=$script:submissionId",'-v',"base_sha=$($script:planDoc.base_sha)",'-v',"head_sha=$($script:planDoc.head_sha)");foreach($k in $extra.Keys){$a+=@('-v',"$k=$($extra[$k])")};$a+=@('-f',$file);$o=&$script:psql @a;if($LASTEXITCODE-ne0){throw "psql exited $LASTEXITCODE"};$z=@($o|Where-Object{$_-match'^\{'});if($z.Count-ne1){throw 'Expected one reconciliation record.'};$z[0]|ConvertFrom-Json}finally{if($null-eq$op){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$op};if($null-eq$oc){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oc}}}
function Invoke-BarrierRace([Net.Http.HttpClient]$http,[string]$token,[string]$payload){
 $pool=[RunspaceFactory]::CreateRunspacePool(1,4);$pool.Open();$ready=[Threading.CountdownEvent]::new(4);$gate=[Threading.ManualResetEventSlim]::new($false);$jobs=@();
 $code={param($c,$t,$json,$r,$g,$i);[void]$r.Signal();if(-not$g.Wait(10000)){throw 'Barrier timeout'};$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$t);$q.Content=[Net.Http.StringContent]::new($json,[Text.Encoding]::UTF8,'application/json');$x=$c.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Index=$i;Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
 try{1..4|ForEach-Object{$ps=[PowerShell]::Create();$ps.RunspacePool=$pool;[void]$ps.AddScript($code).AddArgument($http).AddArgument($token).AddArgument($payload).AddArgument($ready).AddArgument($gate).AddArgument($_);$jobs+=,[pscustomobject]@{PowerShell=$ps;Handle=$ps.BeginInvoke()}};if(-not$ready.Wait(10000)){throw 'Workers did not reach barrier.'};$gate.Set();$results=@();foreach($j in $jobs){$results+=@($j.PowerShell.EndInvoke($j.Handle));if($j.PowerShell.HadErrors){throw 'Concurrent worker failed.'}};$results
 }finally{$gate.Dispose();$ready.Dispose();foreach($j in $jobs){$j.PowerShell.Dispose()};$pool.Close();$pool.Dispose()}
}
function Invoke-Simulation{
 Add-Type -AssemblyName System.Management.Automation;$pool=[RunspaceFactory]::CreateRunspacePool(1,4);$pool.Open();$ready=[Threading.CountdownEvent]::new(4);$gate=[Threading.ManualResetEventSlim]::new($false);$mutex=[Threading.SemaphoreSlim]::new(1,1);$state=[Collections.Concurrent.ConcurrentDictionary[string,int]]::new();$jobs=@();$code={param($r,$g,$m,$s,$i);[void]$r.Signal();if(-not$g.Wait(10000)){throw 'Barrier timeout'};[void]$m.Wait();try{$winner=$s.TryAdd('winner',$i)}finally{$m.Release()|Out-Null};if($winner){'running'}else{'busy'}}
 try{1..4|ForEach-Object{$ps=[PowerShell]::Create();$ps.RunspacePool=$pool;[void]$ps.AddScript($code).AddArgument($ready).AddArgument($gate).AddArgument($mutex).AddArgument($state).AddArgument($_);$jobs+=,[pscustomobject]@{P=$ps;H=$ps.BeginInvoke()}};if(-not$ready.Wait(10000)){throw 'Simulation workers missed barrier.'};$gate.Set();$out=@();foreach($j in $jobs){$out+=@($j.P.EndInvoke($j.H))};if(@($out|Where-Object{$_-ceq'running'}).Count-ne1-or@($out|Where-Object{$_-ceq'busy'}).Count-ne3){throw 'Simulation cardinality failed.'};Write-Output 'PASS simulation one running three busy';Write-Output 'PASS simulation one lease_claim four task_claim journal 43';Write-Output 'CONCURRENT_CLAIM_GATE_SIMULATION_PASS'
 }finally{$mutex.Dispose();$gate.Dispose();$ready.Dispose();foreach($j in $jobs){$j.P.Dispose()};$pool.Close();$pool.Dispose()}
}
if($Simulation){Invoke-Simulation;exit 0}
