 foreach($p in @($PlanPath,$RenewFailReceiptPath,$shared,$pre,$checkpoint,$post,$reconcile,$cert)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "Missing required input: $([IO.Path]::GetFileName($p))"}}
