 $stage='preflight';$scope=PsqlJson $pre @{};Assert-Checks $scope 'preflight';Add-Type -AssemblyName System.Net.Http;$handler=[Net.Http.HttpClientHandler]::new();$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$handler.MaxConnectionsPerServer=8;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.Timeout=[TimeSpan]::FromSeconds(20);$client.DefaultRequestHeaders.Add('apikey',$key);$key=$null
