 [ordered]@{state='PLANNED';staging_ref='lbklqqqbmeyseeccdqog';contract_id=$contractId;submission_id=$submissionId;baseline=36}|ConvertTo-Json|Set-Content -LiteralPath $receipt -Encoding UTF8
 $newDigest=[string]$scope.contract_digest;$writeStarted=$true;$stage='approve';$x=SendAs $reviewer.Token 'approve_contract' @{repository_id=[long]$planDoc.repository_id;id=$contractId.ToString();version=1;digest=$newDigest;document=$scope.contract_document};if($x.Status-lt200-or$x.Status-ge300){throw "Approve HTTP $($x.Status)"};$saved=PsqlJson $checkpoint @{new_digest=$newDigest;expected_events=37};Assert-Checks $saved 'checkpoint-37'
 $stage='submit';$x=SendAs $agent.Token 'submit' @{repository_id=[long]$planDoc.repository_id;id=$submissionId.ToString();contract_id=$contractId.ToString();version=1;digest=$newDigest;head_sha=[string]$planDoc.head_sha};if($x.Status-lt200-or$x.Status-ge300){throw "Submit HTTP $($x.Status)"};$saved=PsqlJson $checkpoint @{new_digest=$newDigest;expected_events=38};Assert-Checks $saved 'checkpoint-38'
 $request=@{repository_id=[long]$planDoc.repository_id;installation_id=[long]$scope.installation_id;repository=[string]$scope.repository;base_ref=[string]$scope.base_ref;id=$submissionId.ToString();delivery=$submissionId.ToString();pr=3;base_sha=[string]$planDoc.base_sha;head_sha=[string]$planDoc.head_sha;digest=$newDigest;verifier='task-completion-v1'};$payload=ConvertTo-Json @{action='claim';request=$request}-Depth 30 -Compress
 $stage='concurrent claims';$started=[Diagnostics.Stopwatch]::StartNew();$responses=@(Invoke-BarrierRace $client $worker.Token $payload);$started.Stop();if($started.Elapsed.TotalSeconds-ge45){throw 'Concurrent window exceeded safety limit.'};if(@($responses).Count-ne4-or@($responses|Where-Object{$_.Status-lt200-or$_.Status-ge300}).Count-ne0){throw 'Unexpected concurrent HTTP response.'};$bodies=@($responses|ForEach-Object{$_.Body|ConvertFrom-Json});if(@($bodies|Where-Object{$_.state-cne'running'}).Count-ne1-or@($bodies|Where-Object{$_.state-cne'busy'}).Count-ne3){throw 'Expected one running and three busy.'};$runIds=@($bodies|ForEach-Object{[string]$_.run_id}|Sort-Object -Unique);if($runIds.Count-ne1){throw 'Multiple run ids returned.'}
 $stage='postcheck';$saved=PsqlJson $post @{};Assert-Checks $saved 'postcheck';if([guid]$saved.run_id-ne[guid]$runIds[0]){throw 'Run reconciliation mismatch.'};[ordered]@{state='CONCURRENT_CLAIM_PASS';staging_ref='lbklqqqbmeyseeccdqog';contract_id=$contractId;submission_id=$submissionId;run_id=$saved.run_id;attempt_id=$saved.attempt_id;fence=1;journal=43}|ConvertTo-Json|Set-Content -LiteralPath $receipt -Encoding UTF8
 Write-Output 'PASS exactly one running and three busy';Write-Output 'PASS one run lease attempt and lease_claim; four task_claim';Write-Output 'CONCURRENT_CLAIM_SINGLE_WINNER_PASS'
}catch{[Console]::Error.WriteLine("FAIL stage=$stage type=$($_.Exception.GetType().Name) message=$($_.Exception.Message)");if($writeStarted){[Console]::Error.WriteLine('DO NOT RETRY. READ-ONLY RECONCILIATION FOLLOWS.');try{$r=PsqlJson $reconcile @{};[Console]::Error.WriteLine(('RECONCILIATION '+(ConvertTo-Json $r -Depth 20 -Compress)))}catch{[Console]::Error.WriteLine('READ-ONLY RECONCILIATION FAILED; stop.')}};exit 1}finally{$key=$dbPassword=$reviewerEmail=$reviewerPassword=$agentEmail=$agentPassword=$workerEmail=$workerPassword=$approval=$null;if($null-ne$reviewer){$reviewer.Token=$null};if($null-ne$agent){$agent.Token=$null};if($null-ne$worker){$worker.Token=$null};Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
